def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    alpha = list(alphabet)
    k = len(alpha)
    mp = {ch: i for i, ch in enumerate(alpha)}
    nxt = [[-1] * k]
    bad = [False]
    for word in banned:
        u = 0
        for ch in word:
            c = mp[ch]
            if nxt[u][c] == -1:
                nxt[u][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            u = nxt[u][c]
        bad[u] = True
    nodes = len(bad)
    fail = [0] * nodes
    from collections import deque
    q = deque()
    for c in range(k):
        v = nxt[0][c]
        if v == -1:
            nxt[0][c] = 0
        else:
            q.append(v)
    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = nxt[u][c]
            if v == -1:
                nxt[u][c] = nxt[fail[u]][c]
            else:
                fail[v] = nxt[fail[u]][c]
                q.append(v)
    ids = [i for i in range(nodes) if not bad[i]]
    index = {s: i for i, s in enumerate(ids)}
    m = len(ids)
    G = [[0] * m for _ in range(m)]
    for s, i in index.items():
        for c in range(k):
            j = index.get(nxt[s][c])
            if j is not None:
                G[i][j] += 1

    def mul(A, B):
        C = [[0] * m for _ in range(m)]
        for i in range(m):
            Ai = A[i]
            Ci = C[i]
            for p in range(m):
                a = Ai[p]
                if a:
                    Bp = B[p]
                    for j in range(m):
                        Ci[j] = (Ci[j] + a * Bp[j]) % MOD
        return C

    R = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    A = G
    e = n
    while e:
        if e & 1:
            R = mul(R, A)
        A = mul(A, A)
        e >>= 1
    return sum(R[index[0]]) % MOD
